=== zimmProductName ===
import React from 'react';
import { Text } from '@chakra-ui/react';

type ZimmProductNameProps = {
  /** The product's display name, already resolved by the caller. */
  name: string;
  /**
   * Heading level. Required rather than defaulted: the correct level depends on what else the
   * page has already emitted, and a silent `h1` default duplicates the base PDP's own
   * screen-reader-only `<h1>Product Details</h1>`.
   */
  as: 'h1' | 'h2' | 'h3';
};

/**
 * Atom — the product name. No recipe: the whole spec is one `textStyle` plus a semantic colour
 * token, which tiers 1-2 of .claude/rules/overrideStyling.md already cover.
 */
export const ZimmProductName = ({ name, as }: ZimmProductNameProps) => (
  <Text as={as} textStyle="heading3" color="text.default" data-testid="product-name">
    {name}
  </Text>
);
=== zimmProductDescription ===
import React from 'react';
import { chakra, useStyleConfig } from '@chakra-ui/react';
import { isBlankRichText, parseRichText } from 'app/utils/richText';

type ZimmProductDescriptionProps = {
  /**
   * The product's long description, as authored in Business Manager. Parsed into React nodes
   * rather than injected as HTML — see `app/utils/richText` for why.
   */
  description?: string;
};

/**
 * Atom — the product description. Renders nothing when the product has no description, so a
 * caller can place it unconditionally.
 */
export const ZimmProductDescription = ({ description }: ZimmProductDescriptionProps) => {
  const styles = useStyleConfig('ZimmProductDescription', {});
  if (isBlankRichText(description)) return null;
  const content = parseRichText(description);

  return (
    <chakra.div __css={styles} textStyle="body2" data-testid="product-description">
      {content}
    </chakra.div>
  );
};
=== zimmProductModelInfo ===
import React from 'react';
import { Text } from '@chakra-ui/react';
import { isBlankRichText, parseRichText } from 'app/utils/richText';

type ZimmProductModelInfoProps = {
  /**
   * Model copy from the product's `c_modelFit` attribute. Business Manager authors this as
   * rich text, so it is parsed rather than rendered as a raw string.
   */
  modelInfo?: string;
};

/**
 * Atom — the model line ("Model is 178cm and wears a size 0"). Renders nothing when
 * `c_modelFit` is absent, which is the common case today. No recipe: one `textStyle` plus a
 * semantic colour token.
 */
export const ZimmProductModelInfo = ({ modelInfo }: ZimmProductModelInfoProps) => {
  if (isBlankRichText(modelInfo)) return null;
  const content = parseRichText(modelInfo);

  return (
    <Text as="div" textStyle="caption" color="text.default" data-testid="product-model-info">
      {content}
    </Text>
  );
};
