import React from 'react';
import { chakra, useMultiStyleConfig } from '@chakra-ui/react';
import { useUiCopy } from 'app/hooks/useUiCopy';

// English fallback for useUiCopy() below — not a prop. Named so the string appears once, the
// same way zimmSubscribeSection/index.tsx keeps its fallbacks.
const LABEL_FALLBACK = 'Style Code:';

type ZimmProductStyleCodeProps = {
  /**
   * The master product's style number. This is the style code shown to shoppers, which is not
